 "content": "from collections import Counter, deque


def transform(grid):
    """Repair isolated intrusions in rectangular color fields; discard stray specks."""
    a = [list(row) for row in grid]
    h, w = len(a), len(a[0])
    background = Counter(v for row in a for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    singleton = set()

    # Only isolated non-background pixels are treated as possible defects.
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = a[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and a[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if color != background and len(component) == 1:
                singleton.add((r, c))

    out = [row[:] for row in a]
    for r, c in singleton:
        # Restore the pixel if it is the sole missing cell of a solid rectangle.
        best = None
        best_area = 0
        for top in range(r + 1):
            for bottom in range(r, h):
                for left in range(c + 1):
                    for right in range(c, w):
                        area = (bottom - top + 1) * (right - left + 1)
                        if area < 4 or area <= best_area:
                            continue
                        target = None
                        valid = True
                        for y in range(top, bottom + 1):
                            for x in range(left, right + 1):
                                if (y, x) == (r, c):
                                    continue
                                v = a[y][x]
                                if v == background or (target is not None and v != target):
                                    valid = False
                                    break
                                target = v
                            if not valid:
                                break
                        if valid:
                            best, best_area = target, area
        if best is not None:
            out[r][c] = best
            continue

        # Multiple defects can occur in one field, so also use a strong local vote.
        votes = Counter(
            a[y][x]
            for dy in (-1, 0, 1)
            for dx in (-1, 0, 1)
            if (dy or dx)
            and 0 <= (y := r + dy) < h
            and 0 <= (x := c + dx) < w
            and a[y][x] != a[r][c]
        )
        if votes:
            target, count = votes.most_common(1)[0]
            bg_count = votes.get(background, 0)
            if target != background and count >= 3 and count > bg_count:
                out[r][c] = target
            else:
                out[r][c] = background
        else:
            out[r][c] = background
    return out


if __name__ == '__main__':
    import json, sys
